async function deleteFile(f){const cid=reportClientId(f);if(!cid){toast('Ouvrez le client avant de supprimer ce fichier.',true);return}if(!confirm('Supprimer « '+f.nom+' » ?'))return;try{await gs('supprimerFichiers',[[f.id],cid]);toast('Fichier supprimé.');st.selected=null;st.pcSelectedFiles.delete(String(f.id));await refreshReportListPC(true);await loadClients(false)}catch(e){toast(e&&e.message||e,true)}}
